local jsCode = [[
(function() {
    // Защита от двойного запуска плагина
    if (window.customThemesFromLoaded) return;
    window.customThemesFromLoaded = true;

    // Создаем элемент <style> для переопределения цветов сайта
    const styleEl = document.createElement('style');
    styleEl.id = 'masyka-from-themes';
    document.head.appendChild(styleEl);

    // CSS стили для пака тем (перебиваем inline-стили через !important)
    const themes = {
        'hacker': `
            div[style*="background-color: rgb(45, 27, 61)"], div[style*="background-color: rgb(61, 37, 80)"] { background-color: #050505 !important; background-image: none !important; }
            .masyka-chat-card, .masyka-sidebar { background-color: #0a0a0a !important; border: 1px solid #00ff00 !important; box-shadow: 0 4px 15px rgba(0, 255, 0, 0.05) !important; }
